def schedule_open_erasure_requests(apps: Any, schema_editor: Any) -> None:
    """Make existing data satisfy the two new constraints.

    Clients used to allow a second open deletion request for the same account. Keep the newest
    and cancel the rest, saying why. Then give every open RECEIVED deletion request a date.
    """

    privacy_request = apps.get_model("identity", "PrivacyRequest")
    now = timezone.now()
    open_requests = privacy_request.objects.filter(
        kind="ERASURE", status__in=("RECEIVED", "IN_REVIEW")
    ).order_by("user_id", "-requested_at")
    kept_for_user: set[Any] = set()
    for item in open_requests:
        if item.user_id in kept_for_user:
            item.status = "CANCELLED"
            item.cancelled_at = now
            item.notes = "Superseded by a later deletion request for the same account."
            item.save(update_fields=("status", "cancelled_at", "notes"))
            continue
        kept_for_user.add(item.user_id)
        if item.status == "RECEIVED" and item.scheduled_for is None:
            item.scheduled_for = max(item.requested_at + _GRACE, now + _MINIMUM_NOTICE)
            item.save(update_fields=("scheduled_for",))


